insert into public.plays (playbook_id, formation_id, set_name, play_name, play_type, concept, primary_scheme,
  secondary_schemes, screen_type, run_concept, pass_concept, rpo_type, play_action, best_vs, weak_vs, blitz_beater,
  man_beater, zone_beater, short_yardage_rating, medium_yardage_rating, long_yardage_rating, red_zone_rating,
  goal_line_rating, two_minute_rating, four_minute_rating, risk_level, explosive_potential, notes, is_seed, owner_id)
select f.playbook_id, f.id, '', v.play_name, v.play_type, v.concept, v.primary_scheme, v.secondary_schemes, v.screen_type,
  v.run_concept, v.pass_concept, v.rpo_type, v.play_action, v.best_vs, v.weak_vs, v.blitz_b, v.man_b, v.zone_b,
  v.sh, v.md, v.lg, v.rz, v.gl, v.tm, v.fm4, v.risk, v.expl,
  'Auto-tagged: play name and formation are from the Madden 27 Atlanta playbook; type, concept, coverage tags and ratings were assigned from the play name. Verify in-game and add the read progression.', true, null
from v
join public.formations f on f.family = v.family and f.name = v.formation
join public.playbooks b on b.id = f.playbook_id and b.name = 'Atlanta'
on conflict do nothing;

insert into public.tags (name) select x from unnest(array['Auto-tagged','Base','Blitz Beater','Bootleg','Bubble','Bunch','Corner','Counter','Crossers','Curl/Flat','Dagger','Draw','Drive','Duo','Flood','Inside Zone','Levels','Man Beater','Mesh','Mid Zone','Mtn Spinner Inside','Option','Option Route','Outside Zone','Pivot/Return','Play Action','Post','Quick','RPO','Run','Scissors','Screen','Shot','Slants','Smash','Spacing','Spot','Stick','Sweep','Trap','Verticals','Wheel','Zone','Zone Beater']) as x on conflict do nothing;

