  ('Gun', 'Trips TE Flex', 'Stick', 'Stick'),
  ('Gun', 'Trips TE Flex', 'Stick', 'Zone Beater'),
  ('Gun', 'Trips TE Flex', 'Stick', 'Auto-tagged'),
  ('Gun', 'Trips TE Flex', 'Verticals', 'Verticals'),
  ('Gun', 'Trips TE Flex', 'Verticals', 'Auto-tagged'),
  ('Gun', 'Trips Y Slot', 'Curls', 'Curl/Flat'),
  ('Gun', 'Trips Y Slot', 'Curls', 'Zone Beater'),
  ('Gun', 'Trips Y Slot', 'Curls', 'Auto-tagged'),
  ('Gun', 'Trips Y Slot', 'Four Verticals', 'Verticals'),
  ('Gun', 'Trips Y Slot', 'Four Verticals', 'Auto-tagged'),
  ('Gun', 'Trips Y Slot', 'Go Dbl Post', 'Shot'),
  ('Gun', 'Trips Y Slot', 'Go Dbl Post', 'Auto-tagged')
)
insert into public.play_tags (play_id, tag_id)
select p.id, tg.id
from pt
join public.formations f on f.family = pt.family and f.name = pt.formation
join public.playbooks b on b.id = f.playbook_id and b.name = 'Atlanta'
join public.plays p on p.formation_id = f.id and lower(p.play_name) = lower(pt.play_name) and p.owner_id is null
join public.tags tg on lower(tg.name) = lower(pt.tag)
on conflict do nothing;

